item(d,6,'Kho policy cập nhật thường xuyên cần cung cấp tri thức mới mà không huấn luyện lại weights. Hướng nào phù hợp?', ['RAG với pipeline cập nhật kho truy xuất','Fine-tune lại chỉ để nạp từng thay đổi nhỏ','Chỉ giữ policy cũ trong một system prompt bất biến','Xóa nguồn và chỉ giữ câu trả lời model nhớ được'],'a','RAG phục vụ tri thức thường đổi; fine-tuning tốn dataset/GPU và phù hợp hơn cho hành vi/format.',kind='scenario',context='Nhân viên cần tra chính sách nội bộ mới nhất và kiểm tra được nguồn.')
item(d,8,'Trạng thái đơn hàng và CRM records khác session preferences ở loại dữ liệu nào?', ['Operational data thay vì contextual data','Cả hai luôn là knowledge document tĩnh','Chỉ dữ liệu training weights','Chỉ metadata của tokenizer'],'a','Operational data là DB/order/ticket/CRM; contextual data là session/profile/preferences/recent actions.')
item(d,10,'Trước khi index corpus nội bộ, những vấn đề governance nào cần được xác định? (Chọn tất cả đáp án đúng.)',['Owner và trách nhiệm cập nhật','ACL, freshness và xử lý PII trước embedding','Chỉ chọn vector DB trước mọi quyết định quyền','Nạp tất cả dữ liệu vì semantic search tự bảo mật'],['a','b'],'Quản trị nguồn, quyền, freshness và PII phải được xét trước index.',kind='multiple_choice')
item(d,14,'Sentence-window retrieval tách bước tìm và bước inject context như thế nào?', ['Index một câu để tìm, inject thêm các câu xung quanh','Index toàn tài liệu thành một vector duy nhất','Gọi LLM viết lại mọi câu thành một mệnh đề độc lập','Chỉ inject câu có score cao nhất, cấm ngữ cảnh lân cận'],'a','Sentence-window giữ tìm chính xác ở mức câu nhưng bổ sung ngữ cảnh khi đưa cho model.')
item(d,14,'Proposition/atomic chunking có đánh đổi nào đáng lưu ý?', ['LLM viết lại thành mệnh đề có thể tốn chi phí và bóp méo nội dung','Không cần kiểm tra chất lượng vì mỗi chunk đã ngắn','Không bao giờ cần model để tách ý','Luôn giữ nguyên mọi định dạng bảng gốc'],'a','Strategy này tạo mệnh đề tự nghĩa nhưng đắt và có rủi ro distortion.')
item(d,15,'Khi corpus là source code, strategy nào phù hợp để tránh cắt giữa hàm/class?', ['Code-aware chunking bằng AST','Cắt cố định theo số byte bất kể cú pháp','Chỉ tách sau mỗi ký tự xuống dòng','Random chunking để tăng đa dạng'],'a','AST parser giúp giữ boundary hàm/class cùng import/signature.')
item(d,15,'Một PDF có nhiều bảng cần cách chunking nào để tránh mất nghĩa header?', ['Table/layout-aware, giữ bảng và lặp header cần thiết','Cắt mỗi ô thành chunk độc lập không giữ header','Bỏ toàn bộ header vì gây trùng token','Chỉ dùng tên file làm context cho mọi hàng'],'a','Table-aware cần layout parser, bảo toàn cấu trúc/ngữ cảnh header.')
item(d,16,'Chunk quá nhỏ và quá lớn tạo ra hai vấn đề nào?', ['Quá nhỏ mất ngữ cảnh; quá lớn trộn chủ đề và inject nhiễu','Quá nhỏ luôn tăng ngữ cảnh; quá lớn luôn chính xác hơn','Cả hai chỉ làm thay đổi số record, không ảnh hưởng retrieval','Chunk lớn tự động giải mọi vấn đề reranking'],'a','Trade-off của chunk size là precision và đủ context, cần eval thay vì đoán.')
item(d,18,'Overlap giúp giải quyết trường hợp nào và phải trả giá gì?', ['Giữ tham chiếu qua ranh giới chunk nhưng tăng dung lượng phần lặp','Loại bỏ mọi nhu cầu metadata mà không tăng storage','Bảo đảm mọi chunk đúng dù nguồn sai','Thay embedding bằng đối sánh filename'],'a','Ví dụ mức tăng trưởng này cần ngữ cảnh ở chunk trước; overlap lưu lặp phần đó.')
item(d,19,'Overlap luôn bắt buộc cho mọi dữ liệu có cấu trúc và mọi kiểu chunking.',None,False,'Bản ghi độc lập, cấu trúc rõ hoặc parent-child/AST có thể không cần overlap.',kind='true_false')
item(d,20,'Retrieval tìm đúng chunk nhưng câu trả lời vẫn thiếu ngữ cảnh xung quanh. Nâng cấp nào phù hợp?', ['Parent-child hoặc sentence-window','Giảm chunk về từng từ và không thêm context','Chỉ tăng similarity threshold đến mức cực cao','Chỉ đổi màu giao diện citation'],'a','Cây quyết định ghép thiếu context với parent-child/sentence-window để thêm vùng đọc.',kind='scenario',context='Query khớp một câu chính sách nhưng điều kiện áp dụng nằm ở đoạn lân cận.')
item(d,25,'Embedding hỗ trợ semantic search bằng cơ chế nào?', ['Biến text thành vector để so độ gần về nghĩa','Chỉ đếm ký tự giống nhau trong filename','Bảo đảm văn bản nguồn luôn là sự thật','Chuyển mọi từ thành cùng một mã định danh'],'a','Vector biểu diễn ngữ nghĩa cho search/clustering/dedup/recommendation, không tạo sự thật.')
item(d,27,'Khi chỉ quan tâm hướng của text embedding và không muốn độ dài vector chi phối, metric nào phù hợp?', ['Cosine similarity','Chỉ độ dài chuỗi văn bản','Euclidean chưa xét scale trong mọi trường hợp','Số dòng của tài liệu nguồn'],'a','Cosine bỏ ảnh hưởng norm; khi norm có ý nghĩa và scale phù hợp mới xét khoảng cách tuyệt đối.')
item(d,29,'Embedding có thể hỗ trợ những tác vụ nào? (Chọn tất cả đáp án đúng.)',['Gom nhóm ticket theo chủ đề','Tìm FAQ gần trùng nội dung','Tự xác nhận nguồn sai thành đúng','Tự áp ACL chỉ từ độ tương đồng'],['a','b'],'Clustering và dedup là use case; embedding không thay chất lượng nguồn hoặc access control.',kind='multiple_choice')
item(d,33,'Metadata giúp retrieval tốt hơn similarity thuần ở những khía cạnh nào? (Chọn tất cả đáp án đúng.)',['Lọc domain/quyền và tránh bản cũ','Truy vết nguồn, section/chunk để cite/debug','Biến một chunk không liên quan thành bằng chứng đúng','Loại bỏ mọi yêu cầu re-index'],['a','b'],'Metadata kết hợp semantic similarity với scope, freshness, quyền và locator.',kind='multiple_choice')
item(d,36,'Đổi embedding model có chi phí chuyển đổi nào khác đổi vector store interface?', ['Thường phải re-index toàn bộ vector theo model mới','Chỉ đổi tên collection là đủ vì mọi vector tương thích','Không cần giữ model version hoặc source text','Chỉ đổi thứ tự query filters'],'a','Vector store interface tương đối tương tự, nhưng thay embedding làm thay hệ vector cần index lại.')
item(d,40,'Một file đuôi.pdf thực tế là scan ảnh. Input validation nên làm gì?', ['Kiểm tra MIME/magic bytes và chọn extractor/OCR phù hợp, log status','Tin đuôi file rồi index chuỗi rỗng như thành công','Bỏ mọi metadata MIME để giảm size','Đổi đuôi sang.txt là đã tạo text thật'],'a','Không chỉ tin extension; thiếu extractor phải fail/skip rõ và log, không index rác.',kind='scenario',context='Pipeline parse không lấy được text nhưng file mở hiển thị toàn ảnh.')
d='p1-d08'
item(d,7,'Ingestion và retrieval khác nhau về thời điểm và sản phẩm đầu ra như thế nào?', ['Ingestion chuẩn bị index; retrieval dùng index theo query để tìm bằng chứng','Ingestion chỉ chạy sau mỗi câu trả lời còn retrieval chỉ chạy một lần','Cả hai chỉ là sinh câu trả lời từ weights','Retrieval thay thế toàn bộ bước làm sạch và metadata'],'a','Ingestion offline/batch chuẩn bị dữ liệu, runtime retrieval chạy mỗi khi user hỏi.')
item(d,13,'Modular RAG đem lại khả năng nào?', ['Compose, thay thế hoặc bỏ qua module theo đặc điểm query','Bắt buộc mọi query chạy cùng một đường cố định','Loại bỏ nhu cầu đo chất lượng từng bước','Gộp retrieval và generation thành một hộp không thể debug'],'a','Tách module cho phép cấu hình linh hoạt thay vì pipeline cứng cho mọi truy vấn.')
item(d,17,'Pre-filtering theo department/access level giúp điều gì trước vector search?', ['Thu scope về tài liệu đúng nghiệp vụ và quyền người dùng','Cho model đọc cả corpus rồi hy vọng không tiết lộ','Chỉ sắp xếp final answer sau khi sinh','Thay mọi kiểm tra quyền bằng similarity score'],'a','Bộ lọc áp trước search giảm noise và giới hạn corpus phù hợp.')
item(d,18,'Query normalization nhằm mục tiêu nào?', ['Chuẩn hóa typo, cách diễn đạt và sự không nhất quán để giảm mơ hồ','Tự thêm factual answer chưa có trong query','Đổi toàn bộ corpus sang một model khác','Loại mọi tên riêng khỏi query dù cần exact match'],'a','Normalization làm sạch/nhất quán query trước retrieval, không tự tạo kiến thức trả lời.')
item(d,21,'Corpus có mã lỗi chính xác và nhiều cách diễn đạt đồng nghĩa. Vì sao hybrid search hữu ích?', ['Kết hợp sparse exact-keyword với dense semantic matching','Dense luôn bắt mọi mã lỗi nên sparse không có ích','Sparse luôn hiểu mọi paraphrase nên dense không cần','Chỉ dùng độ dài query để chọn chunk'],'a','Dense mạnh nghĩa/paraphrase, sparse mạnh exact terms; kết hợp bù điểm yếu.',kind='scenario',context='User vừa hỏi mã ERR cụ thể vừa dùng ngôn ngữ khác với tài liệu.')
item(d,24,'BM25 có thể bỏ sót tài liệu chỉ dùng annual leave khi query là nghỉ phép vì hạn chế nào?', ['Đối sánh từ khóa không tự bảo đảm hiểu đồng nghĩa/đa ngôn ngữ','Không thể đếm tần suất từ','Bắt buộc có GPU mới hoạt động','Không thể xử lý tên riêng'],'a','Lexical search mạnh exact match nhưng dễ hụt paraphrase/synonym nếu không có từ chung.')
item(d,26,'RRF và alpha weighting khác nhau ở dữ liệu dùng để fusion thế nào?', ['RRF dùng thứ hạng; alpha weighting dùng score cần cùng scale','RRF bắt buộc normalize score, alpha chỉ dùng filename','Hai phương pháp luôn cho thứ tự giống nhau','Alpha weighting không bao giờ cần tuning theo domain'],'a','Rank fusion tránh phụ thuộc scale; score fusion cần normalization và tuning trọng số.')
item(d,28,'Thay vì đoán alpha, quy trình chọn alpha nên dựa vào gì?', ['Test set có expected chunks, quét giá trị và đo kết quả top-k','Một giá trị cao nhất dùng cho mọi corpus','Chỉ cảm giác câu trả lời có giọng văn hay','Chỉ tỷ lệ dense/sparse trong source code'],'a','Chọn fusion weight dựa retrieval evaluation trên query đại diện.')
item(d,35,'Vì sao prompt RAG cần tách rõ System, Context và Question?', ['Phân biệt chỉ dẫn, bằng chứng và yêu cầu người dùng','Để mọi text trong retrieved context thành instruction','Để question luôn có thẩm quyền cao hơn policy','Để loại bỏ citation khỏi output'],'a','Delimiter/header rõ giúp model không lẫn các vai trò của từng phần.')
item(d,36,'Document reordering nhằm giảm rủi ro nào?', ['Thông tin quan trọng nằm giữa prompt bị bỏ qua','BM25 không thể index token dài','Mọi tài liệu không có ngày bị tự xóa','Model không thể đọc phần đầu prompt'],'a','Lost in the middle mô tả vị trí giữa dễ bị bỏ sót; reordering cân nhắc vị trí bằng chứng quan trọng.')
item(d,37,'Hai chính sách mâu thuẫn nhưng chunk không mang ngày hoặc version sẽ làm bước conflict resolution khó ở đâu?', ['Không có căn cứ xác định bản mới hơn','Không thể đếm số token','Không thể đặt tên model provider','Không thể biết có bao nhiêu câu trong question'],'a','Thiếu metadata freshness là lỗi indexing bộc lộ khi augmentation phải xử lý xung đột.')
item(d,37,'Những chiến lược xử lý xung đột context nào có thể dùng tùy domain? (Chọn tất cả đáp án đúng.)',['Ưu tiên recency hoặc authority','Nêu rõ xung đột để người dùng quyết định','Luôn chọn chunk dài nhất bất kể nguồn','Luôn hợp nhất mọi con số thành trung bình'],['a','b'],'Recency, authority và surface conflict có mục tiêu/điều kiện khác nhau.',kind='multiple_choice')
item(d,38,'Để tránh đưa dữ liệu trái quyền vào LLM, access filtering nên nằm ở đâu?', ['Trước retrieval/search theo ACL/role phù hợp','Chỉ sau generation khi câu trả lời đã được tạo','Chỉ tại nút copy output trên giao diện','Chỉ dựa vào lời nhắc không tiết lộ bí mật'],'a','Pre-retrieval filtering giới hạn dữ liệu được truy xuất trước khi model tiếp cận.')
item(d,39,'Vì sao không nên dùng toàn bộ context window cho retrieved chunks?', ['Cần headroom cho instructions, query và output','Model không tính token của retrieved text','Context càng dài luôn nâng chất lượng bất kể vị trí','Output có bộ nhớ vô hạn tách khỏi context budget'],'a','Context budget hữu hạn; overfill có thể cắt output hoặc giảm chất lượng.')
item(d,43,'Một factual claim không được nguồn hỗ trợ nên được xử lý thế nào trong generation contract?', ['Không gắn citation giả; nêu thiếu bằng chứng khi không đủ thông tin','Gắn một doc_id bất kỳ để đúng format','Tự thêm source từ trí nhớ nhưng ghi là nguồn đã cung cấp','Luôn trả lời chắc chắn nếu claim nghe hợp lý'],'a','Citation phải support claim; evidence không đủ thì thừa nhận thiếu thông tin.')
item(d,54,'Một retrieval test case nên chứa những gì ngoài question?', ['Ground truth và expected chunk/doc IDs','Chỉ tên model định dùng','Chỉ số ký tự query','Chỉ một rating cảm tính sau demo'],'a','Ground truth đo answer, expected chunks giúp kiểm retrieval đúng evidence.')
item(d,57,'Khi policy bị thu hồi, cách quản lý index nào tránh giữ song song bản không còn hiệu lực?', ['Cập nhật/upsert theo doc_id và xóa thực sự tài liệu bị thu hồi','Chỉ thêm bản mới thành doc_id khác, giữ mọi bản cũ','Chỉ đổi text hiển thị trên UI, không động tới index','Ẩn citation nhưng vẫn để chunk cũ được retrieve'],'a','Freshness đòi index được quản lý liên tục; thu hồi cần delete khỏi vector store.')
d='p1-d09'
item(d,7,'Một agent ôm nhiều vai trò khiến prompt dài và hành vi khó ổn định đang gặp hạn chế nào?', ['Specialization trade-off','Chỉ DNS routing error','Chỉ data serialization','Chỉ model quantization'],'a','Một context/role quá tải khó chuyên môn hóa và ổn định.')
item(d,9,'Khi nào nên cân nhắc multi-agent thay vì thêm agent theo phong trào?', ['Nhiều vai khác nhau, việc độc lập và cần khoanh vùng trách nhiệm/lỗi','Chỉ vì có thể gọi nhiều model cùng lúc','Khi mọi việc đơn giản một bước đã được xử lý tốt','Khi không có cách định nghĩa input/output cho worker'],'a','Multi-agent tăng calls/token/error surface nên cần nhu cầu kiến trúc rõ.')
item(d,12,'Plan-then-execute phù hợp hơn ReAct khi đặc điểm nào đúng?', ['Bài toán đã lộ đủ thông tin từ đầu để lập kế hoạch','Chỉ có thể biết môi trường qua từng hành động','Mỗi tool luôn trả lỗi không thể dự đoán','Không thể viết được bất kỳ mục tiêu nào'],'a','Plan trước thuận lợi khi đã biết đủ; ReAct thích nghi khi thông tin lộ dần qua hành động.')
item(d,13,'Pattern nào phù hợp luồng ổn định, dễ kiểm thử từng bước theo chuỗi?', ['Pipeline','Debate luôn mở vô hạn','Handoff ngẫu nhiên giữa mọi peer','Hierarchical không có owner kết quả'],'a','Pipeline có luồng ổn định; supervisor-worker mạnh routing/trace; debate bổ sung phản biện.')
item(d,17,'Agents-as-tools khác handoff ở quyền tiếp tục hội thoại thế nào?', ['Agents-as-tools trả kết quả về agent gọi; handoff chuyển quyền cho agent được gọi','Cả hai luôn kết thúc cuộc hội thoại','Handoff chỉ là rename của một tool call thuần','Agents-as-tools bắt worker mặc định đọc mọi lịch sử'],'a','Câu kiểm tra là sau lời gọi, ai nói với user; input scope và quyền điều khiển cũng khác.')
item(d,18,'Hai worker cùng cập nhật một field cần hợp nhất kết quả. Thiết kế nào phù hợp?', ['Khai báo reducer/merge policy rõ cho field đó','Dùng global variable để ai ghi cuối thì thắng mà không log','Bỏ state schema để tránh phát hiện lỗi','Luôn coi overwrite im lặng là tổng hợp thành công'],'a','Reducer giải quyết hợp nhất, tránh xung đột hoặc mất giá trị khi overwrite.')
item(d,19,'Vì sao không nên chỉ nối raw output của mọi worker thành context chung?', ['Context phình theo số worker; cần kết luận nén và synthesis có cấu trúc','Raw output luôn ngắn hơn kết luận','Nối chuỗi tự kiểm tra được mọi mâu thuẫn','Càng nhiều raw token luôn tăng reliability'],'a','Worker nên trả kết luận/envelope rõ, supervisor synthesis thay vì concatenate dump.')
item(d,19,'Worker trả None có thể gây vấn đề gì nếu thiếu result envelope có cấu trúc?', ['Lỗi trông giống thành công và supervisor không biết trạng thái thực','Tự động bảo đảm task hoàn thành','Tự bổ sung mọi dữ kiện còn thiếu','Tự làm giảm quyền của các agent khác'],'a','Output cần cấu trúc để phân biệt success, failure và dữ liệu dùng tổng hợp.')
item(d,23,'Những đặc tính nào làm worker dễ kiểm thử và thay thế? (Chọn tất cả đáp án đúng.)',['Một năng lực chuyên biệt với input/output rõ','Stateless khi có thể, lỗi cục bộ không kéo sập toàn hệ','Giữ mọi state trong side effect không ai thấy','Liên tục hỏi supervisor về mọi quyết định nhỏ'],['a','b'],'Worker chuyên môn hóa, testable, ít state và failure isolation giúp reliability.',kind='multiple_choice')
